import json
import os
import subprocess
import sys

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <input_config_path> <output_report_path>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    report_path = sys.argv[2]

    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading config file: {e}", file=sys.stderr)
        sys.exit(1)

    if "token" not in config or "commands" not in config or not isinstance(config["commands"], list):
        print("Invalid config file format", file=sys.stderr)
        sys.exit(1)

    auth_token = config["token"]
    os.environ["AUTH_TOKEN"] = auth_token
    results = []
    error_occurred = False

    for cmd in config["commands"]:
        try:
            result = subprocess.run(
                cmd,
                shell=True,
                check=True,
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=os.environ.copy()
            )
            results.append({
                "command": cmd,
                "stdout": result.stdout.strip()
            })
        except subprocess.CalledProcessError as e:
            error_occurred = True
            results.append({
                "command": cmd,
                "stdout": ""
            })
            break

    if error_occurred:
        results.append({
            "error": f"command failed: {cmd}"
        })

    output = {
        "results": results
    }

    try:
        with open(report_path, 'w') as f:
            json.dump(output, f, indent=2)
    except Exception as e:
        print(f"Error writing report file: {e}", file=sys.stderr)
        sys.exit(1)

    sys.exit(0 if not error_occurred else 1)

if __name__ == "__main__":
    main()

