import sys
import json
import os
import subprocess

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <config_file.json> <report_file.json>", file=sys.stderr)
        sys.exit(1)

    config_file = sys.argv[1]
    report_file = sys.argv[2]

    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading config file: {e}", file=sys.stderr)
        sys.exit(1)

    if "token" not in config or "commands" not in config:
        print("Config must contain 'token' and 'commands' keys", file=sys.stderr)
        sys.exit(1)

    token = config["token"]
    commands = config["commands"]
    results = []
    error_occurred = False

    for cmd in commands:
        env = os.environ.copy()
        env["AUTH_TOKEN"] = token

        try:
            result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True, env=env)
            results.append({
                "command": cmd,
                "stdout": result.stdout
            })
        except subprocess.CalledProcessError as e:
            error_occurred = True
            results.append({
                "command": cmd,
                "stdout": e.stdout
            })
            with open(report_file, 'w') as f:
                report = {
                    "error": f"command failed: {cmd}"
                }
                json.dump(report, f, indent=2)
            sys.exit(1)

    if not error_occurred:
        with open(report_file, 'w') as f:
            json.dump({"results": results}, f, indent=2)

    sys.exit(0)

if __name__ == "__main__":
    main()
